<script setup>
import { computed, ref } from 'vue';
import { api } from '../api';import { session } from '../session';import AppIcon from '../components/AppIcon.vue';import ErrorNotice from '../components/ErrorNotice.vue';
const initials=computed(()=>(session.user.full_name||'').trim().split(/\s+/).slice(0,2).map(p=>p[0]).join('').toUpperCase());
const name=ref(session.user.full_name);const error=ref(null);const message=ref('');const busy=ref(false);
async function save(){busy.value=true;error.value=null;message.value='';try{session.user=(await api('me/',{method:'PATCH',body:{full_name:name.value}})).data;message.value='Nama profil sudah disimpan.';}catch(e){error.value=e;}finally{busy.value=false;}}
</script>
<template><div class="page-heading"><div><div class="eyebrow">AKUN</div><h1>Profil Saya</h1><p class="subtitle">Periksa informasi akun dan perbarui nama lengkap.</p></div></div><div class="card narrow profile-card"><div class="profile-heading"><span class="avatar">{{ initials }}</span><div><h2>{{ session.user.full_name }}</h2><p>{{ session.user.role==='REPORTER'?'Reporter':session.user.role }}</p></div></div><ErrorNotice :error="error"/><p v-if="message" class="notice success" role="status">{{ message }}</p><form method="post" action="#" @submit.prevent="save"><div class="field"><label for="profile-name">Nama lengkap</label><input id="profile-name" v-model="name" name="full_name" autocomplete="name" maxlength="150" required></div><dl class="result-fields"><dt>Email</dt><dd>{{ session.user.email }}</dd><dt>Peran</dt><dd>{{ session.user.role }}</dd><dt>Verifikasi email</dt><dd>{{ session.user.email_verified_at?'Sudah terverifikasi':'Belum terverifikasi' }}</dd></dl><button class="primary" type="submit" :disabled="busy"><AppIcon name="check" :size="16" />{{ busy?'Menyimpan…':'Simpan nama' }}</button></form><p class="fine">Email dan kewenangan akun tidak diubah melalui formulir profil.</p></div></template>
